if c.get('status')!='PASS_ACTUAL_COMMAND_REFUSALS_INDEPENDENT_PENDING' or len(c.get('refusals',[]))!=3 or c['positive_reused']['sha256']!=sha(W/'namebinding-command-progress-result-01.json'):raise ValueError('controls incomplete/stale')
if any(x['exit']==0 or not x['expected_error_seen'] or not x['result_absent'] for x in c['refusals']):raise ValueError('refusal incomplete')
pins=r['source_pins']+r['required_invocation_receipts']
if any(sha(W/x['path'])!=x['sha256'] for x in pins):raise ValueError('source/receipt changed')
paths={x['path'] for x in pins}|{'namebinding-command-progress-method-01.json','namebinding-command-progress-result-01.json','prove-namebinding-command-progress.py','control-namebinding-command-progress.py','freeze-namebinding-command-progress.py'}
paths|={tag+s for tag in ['namebinding-command-progress-positive-01','namebinding-command-progress-controls-run-01'] for s in ['.stdout','.stderr','.status.json']}
