for n in sorted(paths):
    p=out/n;p.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(W/n,p)
(out/'README.md').write_text("# Name-binding command readiness includes skipped optional parts\n\nMethod A STATIC_ONLY. Exact619B original code and separate36B original dispatch\ntable. Shipping EXE73461d0896204b1c259c52f61aef4efbc95a2ffc388cadb36493d5d1d89721f8,\nimagebase120000. Reviewed access-role adapter actually invoked. Complete normal\ncommand CFG resolves its guarded9-target jump locally; no general CFG policy\nwas weakened. Producer valid, independent acceptance/consumption pending.\nFull L1+L2 database goal remains ACTIVE/NOT_MET.\n\nPlayer version: the engine can finish preparing a named resource while skipping\noptional parts. Its ready marker describes that sequence ending; it does not\nguarantee every optional file loaded. A no-longer-pending read also passes through\na separate resource-postprocessing stage.\n\nState0/1 looks up a signed metadata WORD for the selected part. Negative skips\nallocation/read/postprocess and writes slotFFFFFFFF; nonpositive size skips\nlikewise. State7 (or6) advances selector and offsets. Three stable negative WORDs\nfrom initial selector0 finish all3 parts and set18mask02/state9 without this\nroutine's32E620 call. This is a conditional original branch/invariant witness,\nnot a captured authored configuration or three native runs. Valid backed state,\nstable metadata, normal ABI and no interference remain required.\n\nState2 polls the saved request ID at command+30.32E4D0 returns busy1 only for\nnon0/nonFFFFFFFF ID, matching slot generation ID and nonzero slot state.\nA sentinel/stale/inactive case returns0 normally. Zero advances to state3 and\nreturns this invocation; it is not an IO-success result.32E4D0 callee16D6A0\neffects are opaque and cannot be called a drain here.\n\nState3 invokes36D200 on the slot handle; state4 passes it to3A1650; returnFFFFFFFF\nskips to state7. Otherwise state5 waits for3A1290 return2 before advancing.\nThe getter compares the stamped record, returning byte+0C for valid match or0\non mismatch. It is not an arbitrary-ID sanitizer: incomingFFFFFFFF follows a\nzero pointer field read. Fresh postprocessorFFFFFFFF is checked before getter;\nsubsequent state5 still requires valid caller/handle premises.\n\nIncoming state8 selects ready directly; state>8 skips dispatch. HighWORD selector\nis signed and is not generally bounded by the low-state guard. No malformed\nstate safety, actual read acceptance/failure, successful content initialization,\nnatural schedule/reentry/lifetime or global OV closure follows.\n\nReproduce in a writable repo copy with the verified image and fresh output.\nThree actual CLI controls reuse positive01, refusing failed capture, a coherent\nsame-count changed state7 table target, and missing source. All required\nexit/result/exception status is checked; no output result on refusal.\nConsumer: existing FABLE/OPUS namebinding-deletion tasks; SPEC independent\nprimary review. No peer-owned page edit, game/PC/native/emulated run or\ninstrument/save/config/reference/peer mutation. External checks not our runs.\n",encoding='utf8')
members=[dict(path=p.relative_to(out).as_posix(),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(out.rglob('*')) if p.is_file()]
(out/'manifest.json').write_text(json.dumps(dict(status='FROZEN_PRODUCER_VALID_INDEPENDENT_PENDING',members=members,member_count=len(members),native_path_units=units,exe_sha256=r['exe_sha256'],method='A STATIC_ONLY',native_runs=0,live_runs=0,new_whole_runtime_rows_closed=0),indent=2)+'\n')
print(json.dumps(dict(folder=out.name,members=len(members),manifest_sha256=sha(out/'manifest.json'),native_path_units=units)))
